import{_ as d,o as e,c as r,a2 as o}from"./chunks/framework.DGvnA5EY.js";const u=JSON.parse('{"title":"附录 B 场景速查表","description":"> 内容来源：WorkBuddy 官方指南（非官方整理，© 本指南作者，保留所有权利） 前面 28 章按\\"功能\\"和\\"案例\\"组织，你得记住某个功能在哪一章。这份附录反过来——按你想干的事查。","frontmatter":{"title":"附录 B 场景速查表"},"headers":[],"relativePath":"bluebook/附录/附录 B 场景速查表/index.md","filePath":"bluebook/附录/附录 B 场景速查表/index.md","lastUpdated":1792132442000}'),a={name:"bluebook/附录/附录 B 场景速查表/index.md"};function h(c,t,l,i,n,b){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="附录-b-场景速查表" tabindex="-1">附录 B 场景速查表 <a class="header-anchor" href="#附录-b-场景速查表" aria-label="Permalink to &quot;附录 B 场景速查表&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南（非官方整理，© 本指南作者，保留所有权利）</p></blockquote><h2 id="这份附录是干什么的" tabindex="-1">这份附录是干什么的 <a class="header-anchor" href="#这份附录是干什么的" aria-label="Permalink to &quot;这份附录是干什么的&quot;">​</a></h2><p>前面 28 章按&quot;功能&quot;和&quot;案例&quot;组织，你得记住某个功能在哪一章。这份附录反过来——<strong>按你想干的事查</strong>。</p><p>用法只有一句：<strong>在左边找到你卡住的那件事，右边直接看该开什么、去哪一章。</strong></p><hr><h2 id="一、按场景查-我要干-x-该用什么" tabindex="-1">一、按场景查（我要干 X，该用什么） <a class="header-anchor" href="#一、按场景查-我要干-x-该用什么" aria-label="Permalink to &quot;一、按场景查（我要干 X，该用什么）&quot;">​</a></h2><h3 id="办公三件套" tabindex="-1">办公三件套 <a class="header-anchor" href="#办公三件套" aria-label="Permalink to &quot;办公三件套&quot;">​</a></h3><table tabindex="0"><thead><tr><th>我要做的事</th><th>用什么</th><th>详见</th></tr></thead><tbody><tr><td>写一份正式文档/报告</td><td><code>docx</code>（Word 生成）或 <code>tencent-docx</code>（排版美化）</td><td>第 11 章</td></tr><tr><td>改一份已有的 Word</td><td><code>tencent-local-office-edit</code>（实时读写本机文件）</td><td>第 11 章</td></tr><tr><td>做表格、算数据、透视</td><td><code>xlsx</code> 或 <code>tencent-docs-sheet-generation</code>（新建）/ <code>sheetagent</code>（处理已有表）</td><td>第 11 章</td></tr><tr><td>做 PPT</td><td><code>pptx</code> 或 <code>tencent-pptx</code></td><td>第 11 章</td></tr><tr><td>三件套一起要</td><td>同一任务里分三步交付，先文档再表格再 PPT</td><td>第 11 章</td></tr></tbody></table><h3 id="文件与整理" tabindex="-1">文件与整理 <a class="header-anchor" href="#文件与整理" aria-label="Permalink to &quot;文件与整理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>我要做的事</th><th>用什么</th><th>详见</th></tr></thead><tbody><tr><td>整理乱糟糟的桌面/文件夹</td><td>文件整理 + 用附录 A 模板 4（拆步骤）</td><td>第 12 章</td></tr><tr><td>批量重命名、按规则归档</td><td>让它先给方案再执行（附录 A 模板 7）</td><td>第 12 章</td></tr><tr><td>从一堆资料里提炼要点</td><td>给上下文 + 分批处理（模板 3、4）</td><td>第 12、16 章</td></tr></tbody></table><h3 id="浏览器与自动化" tabindex="-1">浏览器与自动化 <a class="header-anchor" href="#浏览器与自动化" aria-label="Permalink to &quot;浏览器与自动化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>我要做的事</th><th>用什么</th><th>详见</th></tr></thead><tbody><tr><td>自动打开网页、点按钮、抓内容</td><td><code>browser-automation</code> 或 <code>agent-browser</code></td><td>第 13 章</td></tr><tr><td>让它定时抓某个网页更新</td><td>浏览器自动化 + 定时任务</td><td>第 10、15 章</td></tr><tr><td>用网页做测试/截图</td><td><code>playwright-cli</code></td><td>第 13 章</td></tr></tbody></table><h3 id="资讯与知识管理" tabindex="-1">资讯与知识管理 <a class="header-anchor" href="#资讯与知识管理" aria-label="Permalink to &quot;资讯与知识管理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>我要做的事</th><th>用什么</th><th>详见</th></tr></thead><tbody><tr><td>每天汇总资讯成一份简报</td><td>RSS/抓取 + 定时任务 + 推送</td><td>第 15 章</td></tr><tr><td>把收藏的内容变成能再用的知识</td><td>结构化整理 + 定期回顾</td><td>第 16 章</td></tr><tr><td>会议结束自动出纪要并落任务</td><td>腾讯会议连接器 + 模板 4 拆步骤</td><td>第 17 章</td></tr></tbody></table><h3 id="内容创作与多媒体" tabindex="-1">内容创作与多媒体 <a class="header-anchor" href="#内容创作与多媒体" aria-label="Permalink to &quot;内容创作与多媒体&quot;">​</a></h3><table tabindex="0"><thead><tr><th>我要做的事</th><th>用什么</th><th>详见</th></tr></thead><tbody><tr><td>生成视频</td><td><code>VideoGen</code></td><td>第 19 章</td></tr><tr><td>生成图片、配图、封面</td><td><code>ImageGen</code>；抠图修图用 <code>buddy-image-processing</code></td><td>第 19、23 章</td></tr><tr><td>3D 模型/模板化视频</td><td><code>buddy-multimodal-generation</code></td><td>第 19 章</td></tr><tr><td>让文章被 AI 搜到（GEO）</td><td>内容工作台 + 结构化改写</td><td>第 21 章</td></tr></tbody></table><h3 id="进阶系统" tabindex="-1">进阶系统 <a class="header-anchor" href="#进阶系统" aria-label="Permalink to &quot;进阶系统&quot;">​</a></h3><table tabindex="0"><thead><tr><th>我要做的事</th><th>用什么</th><th>详见</th></tr></thead><tbody><tr><td>把一本书/一个视频变成可复用的 Skill</td><td><code>skill-creator</code>（蒸馏流水线）</td><td>第 22 章</td></tr><tr><td>不知道该装什么技能</td><td><code>find-skills</code>（说需求，它帮你配装）</td><td>第 5、22 章</td></tr><tr><td>多个 Agent 分工干活</td><td>多 Agent 架构设计 + SOP 编排</td><td>第 24 章</td></tr><tr><td>定时任务跑久了会乱/会死</td><td>心跳 + 对账 + 幂等</td><td>第 25 章</td></tr></tbody></table><h3 id="岗位与行业" tabindex="-1">岗位与行业 <a class="header-anchor" href="#岗位与行业" aria-label="Permalink to &quot;岗位与行业&quot;">​</a></h3><table tabindex="0"><thead><tr><th>我要做的事</th><th>用什么</th><th>详见</th></tr></thead><tbody><tr><td>想知道我这个岗位该怎么用</td><td>按岗位查路线图（新媒体/产品/HR/市场/教师/创业者）</td><td>第 26 章</td></tr><tr><td>想知道我这个行业该怎么落地</td><td>按行业查工作流（教培/餐饮等）</td><td>第 27 章</td></tr><tr><td>想把 AI 变成一支团队</td><td>四步组队法 + 人类角色定位</td><td>第 28 章</td></tr></tbody></table><h3 id="官方能力入口-第一篇" tabindex="-1">官方能力入口（第一篇） <a class="header-anchor" href="#官方能力入口-第一篇" aria-label="Permalink to &quot;官方能力入口（第一篇）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>我要做的事</th><th>用什么</th><th>详见</th></tr></thead><tbody><tr><td>让它动手碰我的文件</td><td>先给文件夹授权</td><td>第 1、2 章</td></tr><tr><td>让它代表我访问邮箱/文档/企微</td><td>连接器 + 扫码授权</td><td>第 7 章</td></tr><tr><td>手机上远程指挥电脑</td><td>小程序 / IM 助理 + 扫码绑定</td><td>第 8 章</td></tr><tr><td>接一个官方没提供的外部服务</td><td>自定义 MCP 服务 + 改 <code>mcp.json</code></td><td>第 9 章</td></tr><tr><td>到点自动干活</td><td>自动化任务 + 权限模式 + 推送</td><td>第 10 章</td></tr><tr><td>换个专业视角看稿子</td><td>专家 / 专家团</td><td>第 6 章</td></tr></tbody></table><blockquote><p>第二～四篇的完整实操提示词属于付费内容，见购买指南。</p></blockquote><hr><h2 id="二、按工具查-我只知道工具名-不知道用在哪" tabindex="-1">二、按工具查（我只知道工具名，不知道用在哪） <a class="header-anchor" href="#二、按工具查-我只知道工具名-不知道用在哪" aria-label="Permalink to &quot;二、按工具查（我只知道工具名，不知道用在哪）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具/技能</th><th>一句话用途</th><th>首次出现</th></tr></thead><tbody><tr><td><code>find-skills</code></td><td>你说需求，它帮你找现成 Skill（新手最常用）</td><td>第 5 章</td></tr><tr><td><code>skill-creator</code></td><td>把跑顺的活固化成专属 Skill / 把书和视频蒸馏成 Skill</td><td>第 22 章</td></tr><tr><td><code>docx</code></td><td>生成/编辑 Word 文档</td><td>第 11 章</td></tr><tr><td><code>xlsx</code></td><td>生成和处理 Excel 表格</td><td>第 11 章</td></tr><tr><td><code>pptx</code></td><td>生成和处理 PPT</td><td>第 11 章</td></tr><tr><td><code>browser-automation</code></td><td>浏览器自动化：打开、点击、抓取</td><td>第 13 章</td></tr><tr><td><code>agent-browser</code></td><td>浏览器自动化（含截图、抽取内容）</td><td>第 13 章</td></tr><tr><td><code>playwright-cli</code></td><td>网页测试、表单填写、截图、数据提取</td><td>第 13 章</td></tr><tr><td><code>ImageGen</code></td><td>文生图/图生图</td><td>第 19 章</td></tr><tr><td><code>VideoGen</code></td><td>文生视频/图生视频</td><td>第 19 章</td></tr><tr><td><code>buddy-image-processing</code></td><td>抠图、修图、去水印、人像美化</td><td>第 19 章</td></tr><tr><td><code>buddy-multimodal-generation</code></td><td>3D 模型、模板化图生视频</td><td>第 19 章</td></tr><tr><td><code>tencent-docx</code></td><td>Word 专业排版与美化</td><td>第 11 章</td></tr><tr><td><code>tencent-pptx</code></td><td>PPT 生成与编辑</td><td>第 11 章</td></tr><tr><td><code>tencent-docs-sheet-generation</code></td><td>从零新建 Excel</td><td>第 11 章</td></tr><tr><td><code>tencent-local-office-edit</code></td><td>编辑本机已有的 Word/Excel</td><td>第 11 章</td></tr><tr><td><code>stock-advisor</code></td><td>单只股票端到端分析（技术面+基本面+排版）</td><td>第 18 章</td></tr><tr><td><code>a-share-analyst</code></td><td>A 股日常行情、技术指标、选股</td><td>第 18 章</td></tr><tr><td><code>financial-expert</code></td><td>金融数据查询与筛选（依赖数据源 MCP）</td><td>第 18 章</td></tr><tr><td><code>peers-advisory-group</code></td><td>多视角决策讨论（交叉辩论）</td><td>第 18 章</td></tr></tbody></table><blockquote><p>Skill 以 SkillHub 实际上线为准，装前认准官方源，第三方 Skill 质量参差不齐。</p></blockquote><hr><h2 id="三、按卡点查-我是什么状态" tabindex="-1">三、按卡点查（我是什么状态） <a class="header-anchor" href="#三、按卡点查-我是什么状态" aria-label="Permalink to &quot;三、按卡点查（我是什么状态）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我的状态</th><th>怎么办</th><th>详见</th></tr></thead><tbody><tr><td>打开软件不知道从哪开始</td><td>从第 4 章&quot;第一个任务&quot;开始</td><td>第 4 章</td></tr><tr><td>界面太乱找不到功能</td><td>导航栏 / 自定义菜单</td><td>第 3 章</td></tr><tr><td>AI 说&quot;它什么都能做&quot;，结果做不到</td><td>预期误区 + 五问定标</td><td>第 1 章、附录 A 模板 1</td></tr><tr><td>AI 把它该我的活也干了</td><td>权限模式 / 权限边界三条</td><td>第 7、10 章</td></tr><tr><td>AI 编了一个不存在的功能</td><td>检查是不是把 Skill 想象得太全能；用 <code>find-skills</code> 找现成的</td><td>第 1、5 章</td></tr><tr><td>任务卡在&quot;待确认&quot;不动</td><td>它在等你回话</td><td>第 3 章</td></tr><tr><td>跑完看不出好坏</td><td>验收标准（附录 A 模板 5）</td><td>附录 A</td></tr><tr><td>改了文件不敢放心</td><td>变更 Diff + 先备份</td><td>第 3 章、附录 A 模板 7</td></tr><tr><td>定时任务跑久了会乱</td><td>可靠性三原则 + 心跳对账</td><td>第 25 章</td></tr><tr><td>授权的连接器想关掉</td><td>停止使用 vs 解绑</td><td>第 7 章</td></tr><tr><td>密钥/token 泄露了</td><td>撤销连接器 + 换密钥</td><td>第 7、9 章</td></tr></tbody></table><hr><h2 id="本附录任务清单" tabindex="-1">本附录任务清单 <a class="header-anchor" href="#本附录任务清单" aria-label="Permalink to &quot;本附录任务清单&quot;">​</a></h2><ul><li>[ ] 收藏这一页，遇到卡点先来这里搜状态</li><li>[ ] 挑 3 个你天天干的活，找到对应章节去补读</li><li>[ ] 确认 <code>find-skills</code> 已装（不知道装什么时它是入口）</li></ul><hr><p><em>本指南为第三方非官方整理，版权归作者所有，转载请注明出处。</em></p>',36)])])}const x=d(a,[["render",h]]);export{u as __pageData,x as default};
